const listNotifications = `-- name: ListNotifications :many
SELECT n.id, n.kind, n.detail, n.created_at, n.read_at, n.done_at,
       n.actor_id, COALESCE(a.name, '')::text AS actor_name,
       n.project_id, COALESCE(p.name, '')::text AS project_name,
       n.issue_id, COALESCE(i.number, 0)::int AS issue_number, COALESCE(i.title, '')::text AS issue_title,
       COALESCE(i.status, '')::text AS issue_status, COALESCE(p.issue_key, '')::text AS issue_key,
       COALESCE(p.issue_key_digits, o.issue_key_digits, 0)::int AS digits,
       n.pull_request_id, COALESCE(pr.number, 0)::int AS pull_number, COALESCE(pr.title, '')::text AS pull_title,
       COALESCE(pr.state, '')::text AS pull_state, COALESCE(r.name, '')::text AS repository,
       n.page_id, COALESCE(d.title, '')::text AS page_title
FROM notifications n
LEFT JOIN users a ON a.id = n.actor_id
LEFT JOIN projects p ON p.id = n.project_id
LEFT JOIN organizations o ON o.id = n.org_id
LEFT JOIN issues i ON i.id = n.issue_id
LEFT JOIN pull_requests pr ON pr.id = n.pull_request_id
LEFT JOIN repositories r ON r.id = pr.repository_id
LEFT JOIN doc_pages d ON d.id = n.page_id
WHERE n.user_id = $1 AND n.org_id = $2
  AND (n.done_at IS NOT NULL) = $3::bool
  AND (NOT $3::bool OR n.done_at > now() - interval '30 days')
  AND (NOT $4::bool OR n.read_at IS NULL)
  AND (cardinality($5::text[]) = 0 OR n.kind = ANY($5::text[]))
  AND (NOT $6::bool OR (n.created_at, n.id) < ($7::timestamptz, $8::bigint))
ORDER BY n.created_at DESC, n.id DESC
LIMIT $9
`

type ListNotificationsParams struct {
	UserID    pgtype.UUID        `json:"user_id"`
	OrgID     pgtype.UUID        `json:"org_id"`
	Done      bool               `json:"done"`
	Unread    bool               `json:"unread"`
	Kinds     []string           `json:"kinds"`
	HasCursor bool               `json:"has_cursor"`
	CursorAt  pgtype.Timestamptz `json:"cursor_at"`
	CursorID  int64              `json:"cursor_id"`
	RowLimit  int32              `json:"row_limit"`
}

type ListNotificationsRow struct {
	ID            int64              `json:"id"`
	Kind          string             `json:"kind"`
	Detail        []byte             `json:"detail"`
	CreatedAt     pgtype.Timestamptz `json:"created_at"`
	ReadAt        pgtype.Timestamptz `json:"read_at"`
	DoneAt        pgtype.Timestamptz `json:"done_at"`
	ActorID       pgtype.UUID        `json:"actor_id"`
	ActorName     string             `json:"actor_name"`
	ProjectID     pgtype.UUID        `json:"project_id"`
	ProjectName   string             `json:"project_name"`
	IssueID       pgtype.UUID        `json:"issue_id"`
	IssueNumber   int32              `json:"issue_number"`
	IssueTitle    string             `json:"issue_title"`
	IssueStatus   string             `json:"issue_status"`
	IssueKey      string             `json:"issue_key"`
	Digits        int32              `json:"digits"`
	PullRequestID pgtype.UUID        `json:"pull_request_id"`
	PullNumber    int32              `json:"pull_number"`
	PullTitle     string             `json:"pull_title"`
	PullState     string             `json:"pull_state"`
	Repository    string             `json:"repository"`
	PageID        pgtype.UUID        `json:"page_id"`
	PageTitle     string             `json:"page_title"`
}

// A person's updates in a workspace, newest first, with what they are
// about as it is now.
func (q *Queries) ListNotifications(ctx context.Context, arg ListNotificationsParams) ([]ListNotificationsRow, error) {
	rows, err := q.db.Query(ctx, listNotifications,
		arg.UserID,
		arg.OrgID,
		arg.Done,
		arg.Unread,
		arg.Kinds,
		arg.HasCursor,
		arg.CursorAt,
		arg.CursorID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListNotificationsRow{}
	for rows.Next() {
		var i ListNotificationsRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.Detail,
			&i.CreatedAt,
			&i.ReadAt,
			&i.DoneAt,
			&i.ActorID,
			&i.ActorName,
			&i.ProjectID,
			&i.ProjectName,
			&i.IssueID,
			&i.IssueNumber,
			&i.IssueTitle,
			&i.IssueStatus,
			&i.IssueKey,
			&i.Digits,
			&i.PullRequestID,
			&i.PullNumber,
			&i.PullTitle,
			&i.PullState,
			&i.Repository,
			&i.PageID,
			&i.PageTitle,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

