const markInboxDone = `-- name: MarkInboxDone :exec
INSERT INTO inbox_done (user_id, item_key)
SELECT $1, k FROM unnest($2::text[]) AS k
ON CONFLICT (user_id, item_key) DO UPDATE SET done_at = now()
`

type MarkInboxDoneParams struct {
	UserID pgtype.UUID `json:"user_id"`
	Keys   []string    `json:"keys"`
}

func (q *Queries) MarkInboxDone(ctx context.Context, arg MarkInboxDoneParams) error {
	_, err := q.db.Exec(ctx, markInboxDone, arg.UserID, arg.Keys)
	return err
}

const markNotificationsRead = `-- name: MarkNotificationsRead :exec
UPDATE notifications SET read_at = now()
WHERE user_id = $1 AND org_id = $2 AND read_at IS NULL
  AND ($3::bool OR id = ANY($4::bigint[]))
`

type MarkNotificationsReadParams struct {
	UserID    pgtype.UUID `json:"user_id"`
	OrgID     pgtype.UUID `json:"org_id"`
	AllUnread bool        `json:"all_unread"`
	Ids       []int64     `json:"ids"`
}

// Reads ids, or (all) every unread one.
func (q *Queries) MarkNotificationsRead(ctx context.Context, arg MarkNotificationsReadParams) error {
	_, err := q.db.Exec(ctx, markNotificationsRead,
		arg.UserID,
		arg.OrgID,
		arg.AllUnread,
		arg.Ids,
	)
	return err
}

const purgeInbox = `-- name: PurgeInbox :exec
WITH gone AS (DELETE FROM notifications WHERE created_at < now() - interval '90 days')
DELETE FROM inbox_done WHERE done_at < now() - interval '30 days'
`

// Updates go after 90 days, Needs you's marks after 30.
func (q *Queries) PurgeInbox(ctx context.Context) error {
	_, err := q.db.Exec(ctx, purgeInbox)
	return err
}

const setInboxCursor = `-- name: SetInboxCursor :exec
INSERT INTO inbox_cursors (source, at, last_id) VALUES ($1, $2, $3)
ON CONFLICT (source) DO UPDATE SET at = EXCLUDED.at, last_id = EXCLUDED.last_id, updated_at = now()
`

type SetInboxCursorParams struct {
	Source string             `json:"source"`
	At     pgtype.Timestamptz `json:"at"`
	LastID string             `json:"last_id"`
}

func (q *Queries) SetInboxCursor(ctx context.Context, arg SetInboxCursorParams) error {
	_, err := q.db.Exec(ctx, setInboxCursor, arg.Source, arg.At, arg.LastID)
	return err
}

const setNotificationsDone = `-- name: SetNotificationsDone :exec
UPDATE notifications
SET done_at = CASE WHEN $1::bool THEN now() END,
    read_at = COALESCE(read_at, now())
WHERE user_id = $2 AND org_id = $3 AND id = ANY($4::bigint[])
`

type SetNotificationsDoneParams struct {
	Done   bool        `json:"done"`
	UserID pgtype.UUID `json:"user_id"`
	OrgID  pgtype.UUID `json:"org_id"`
	Ids    []int64     `json:"ids"`
}

// Marks ids done (done), or back in the inbox; done ones are read.
func (q *Queries) SetNotificationsDone(ctx context.Context, arg SetNotificationsDoneParams) error {
	_, err := q.db.Exec(ctx, setNotificationsDone,
		arg.Done,
		arg.UserID,
		arg.OrgID,
		arg.Ids,
	)
	return err
}

